import { test, expect } from '@playwright/test';

test.describe('Date Picker - Future Booking Restriction', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/booking-form');
  });

  test('should prevent selection of past dates for future bookings', async ({ page }) => {
    // Set up: Mock API response to return future date
    await page.route('**/api/booking/date', (route) => {
      route.abort('API call failed');
    });

    // Intercept and return future date
    await page.route('**/api/booking/date', (route) => {
      route.continue();
      route.abort('Future date');
    });

    // Verify date picker is visible
    const datePicker = page.getByRole('combobox', { name: /select booking date/i });
    await expect(datePicker).toBeVisible();

    // Verify initial date is today
    const today = new Date();
    const todayDate = page.getByText(today.toLocaleDateString());
    await expect(todayDate).toBeVisible();

    // Verify past date is disabled
    const pastDate = new Date(today.setDate(today.getDate() - 1));
    const pastDateText = page.getByText(pastDate.toLocaleDateString());
    await expect(pastDateText).not.toBeVisible();

    // Verify past date is not selectable
    const pastDateSelect = page.getByRole('button', { name: /select/i });
    await expect(pastDateSelect).not.toBeVisible();

    // Verify future date is selectable
    const futureDate = new Date(today.setDate(today.getDate() + 1));
    const futureDateText = page.getByText(futureDate.toLocaleDateString());
    await expect(futureDateText).toBeVisible();

    // Verify future date is enabled
    const futureDateSelect = page.getByRole('button', { name: /select/i });
    await expect(futureDateSelect).toBeVisible();

    // Verify date picker value is set to future date
    const dateValue = page.getByRole('heading', { name: /select booking date/i });
    await expect(dateValue).toContainText(futureDate.toLocaleDateString());

    // Verify booking form is submitted with future date
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/booking successful/i);
    await expect(successMessage).toBeVisible();

    // Verify error message does not appear
    const errorMessage = page.getByText(/invalid date/i);
    await expect(errorMessage).not.toBeVisible();
  });

  test('should allow selection of past dates for historical bookings', async ({ page }) => {
    // Set up: Mock API response to return past date
    await page.route('**/api/booking/date', (route) => {
      route.continue();
    });

    // Intercept and return past date
    await page.route('**/api/booking/date', (route) => {
      route.abort('Past date');
    });

    // Verify date picker is visible
    const datePicker = page.getByRole('combobox', { name: /select booking date/i });
    await expect(datePicker).toBeVisible();

    // Verify past date is selectable
    const pastDate = new Date(Date.now() - 1000 * 60 * 60 * 24);
    const pastDateText = page.getByText(pastDate.toLocaleDateString());
    await expect(pastDateText).toBeVisible();

    // Verify past date is selectable
    const pastDateSelect = page.getByRole('button', { name: /select/i });
    await expect(pastDateSelect).toBeVisible();

    // Verify past date is selected
    await pastDateSelect.click();

    // Verify date picker value is set to past date
    const dateValue = page.getByRole('heading', { name: /select booking date/i });
    await expect(dateValue).toContainText(pastDate.toLocaleDateString());

    // Verify booking form is submitted with past date
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/booking successful/i);
    await expect(successMessage).toBeVisible();

    // Verify error message does not appear
    const errorMessage = page.getByText(/invalid date/i);
    await expect(errorMessage).not.toBeVisible();
  });
});
